using Microsoft.AspNetCore.Mvc; using VeterinariaMVC.Models; namespace VeterinariaMVC.Controllers; public class VeterinariaController:Controller{static List<Animal> animais=new(){new Animal{Id=1,Nome="Rex",Especie="Cachorro",Idade=5,Dono="Ana"},new Animal{Id=2,Nome="Mia",Especie="Gato",Idade=3,Dono="Bruno"},new Animal{Id=3,Nome="Thor",Especie="Cachorro",Idade=2,Dono="Carla"},new Animal{Id=4,Nome="Luna",Especie="Gato",Idade=4,Dono="Diego"},new Animal{Id=5,Nome="Bob",Especie="Cachorro",Idade=7,Dono="Eduarda"},new Animal{Id=6,Nome="Nina",Especie="Gato",Idade=1,Dono="Felipe"},new Animal{Id=7,Nome="Max",Especie="Cachorro",Idade=6,Dono="Giovana"},new Animal{Id=8,Nome="Mel",Especie="Gato",Idade=2,Dono="Henrique"}}; public IActionResult Index()=>View(animais); public IActionResult Cachorros()=>View(animais.Where(x=>x.Especie=="Cachorro")); public IActionResult Gatos()=>View(animais.Where(x=>x.Especie=="Gato"));}